"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
  "params": {
    "containers": {
      "api": {
        "requests": {
          "cpu": "250m"
        },
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "The 'api' container's CPU limit will be increased from 500m to 750m, reducing throttling and improving readiness probe success rates.",
  "rationale": "The container is using 0.495 CPU (99% of its 0.5 limit) and is throttled 64% of the time. The new version (revision 2) uses more CPU than the previous version (revision 1), which ran unthrottled for 200h compared to 140h. Raising the limit to 750m will provide enough CPU to avoid throttling without requiring node-level changes.",
